MATCH (p:PlantItem:CentrifugalPump)
WHERE toString(p.unit_id) = '45'
RETURN count(p) AS pump_count, collect(p.tag) AS tags;

MATCH (:PlantItem {tag: "P-4904"})-[:measured_by]->(instrument)
RETURN instrument.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:ButterflyValve)
WHERE v.unit_id = "60"
RETURN count(v) AS butterfly_valve_count, collect(v.tag) AS tags;

MATCH (source:PlantItem {tag: "M-3501"}), (target:PlantItem {tag: "P-4001"})
RETURN source.tag AS from_tag, target.tag AS to_tag,
       EXISTS {
         MATCH (source)-[:send_to*1..]->(target)
       } AS can_reach

MATCH (v:PlantItem:ButterflyValve)
WHERE toString(v.unit_id) = '35'
RETURN count(v) AS count, collect(v.tag) AS tags;

MATCH (v:PlantItem:ButterflyValve)
WHERE toString(v.unit_id) = '11'
RETURN count(v) AS numberOfButterflyValves, collect(v.tag) AS tags;

MATCH (equipment:PlantItem {tag: "M-2301"})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (tank:Tank {tag: "TK-2103"})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:ActuatingFunction)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment {tag: "EA-4001"})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:ActuatingFunction)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (s:PlantItem {tag: 'E-5701'}), (t:PlantItem {tag: 'V-5701'}),
      p = shortestPath((s)-[:send_to*]->(t))
RETURN [n IN nodes(p) | n.tag] AS path_tags;

MATCH (equipment:PlantItem {tag: "V-401"})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:PlantItem)<-[:send_signal_to]-(controller:ProcessControlFunction)
RETURN DISTINCT controller.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'TK-101'})
WHERE NOT (source)<-[:send_to]-()
RETURN DISTINCT source.tag AS tag;

MATCH (item:PlantItem {tag: 'D-3001'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (s:PlantItem {tag: "TK-2701"}), (t:PlantItem {tag: "V-2801"})
MATCH p = shortestPath((s)-[:send_to*1..]->(t))
RETURN [n IN nodes(p) | n.tag] AS flow_path_tags;

MATCH (p:PlantItem:ProcessColumn)
