MATCH (equipment:PlantItem {tag: 'V-4101'})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:PlantItem)<-[:send_signal_to]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.loop_tag AS loop_tag
ORDER BY loop_tag;

MATCH (item:PlantItem {tag: "EA-801"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "V-1201"})-[:send_to]-(valve:PlantItem)<-[:control]-(actuator:PlantItem)<-[:send_signal_to]-(controller:PlantItem)
RETURN DISTINCT controller.loop_tag AS loop_tag
)

MATCH (source:PlantItem)-[:send_to*1..]->(tank:PlantItem {tag: 'TK-104'})
WHERE NOT EXISTS {
  MATCH ()-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (s:PlantItem {tag: "E-5002"}), (t:PlantItem {tag: "P-5002"}),
      p = shortestPath((s)-[:send_to*1..]->(t))
RETURN [item IN nodes(p) | item.tag] AS flow_path;

MATCH (s:PlantItem {tag: 'P-3202'}), (t:PlantItem {tag: 'EA-3501'})
WITH s, t, EXISTS {
  MATCH p = (s)-[:send_to*]->(t)
  WHERE all(n IN nodes(p) WHERE n.tag <> 'GTV-34001')
} AS can_flow
RETURN s.tag AS source_tag, t.tag AS destination_tag, can_flow AS can_flow_without_GTV_34001;

MATCH (source:PlantItem {tag: "R-2401"}), (target:PlantItem {tag: "P-2701"})
RETURN source.tag AS from_tag, target.tag AS to_tag,
       EXISTS { MATCH (source)-[:send_to*1..]->(target) } AS can_reach;

MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'P-502B'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (s:PlantItem {tag: "TK-702"}), (t:PlantItem {tag: "M-2901"})
OPTIONAL MATCH p = shortestPath((s)-[:send_to*]->(t))
RETURN p IS NOT NULL AS can_reach, [n IN nodes(p) | n.tag] AS tags;

MATCH (s:PlantItem {tag: 'P-902B'}), (t:PlantItem {tag: 'V-301'})
MATCH p = shortestPath((s)-[:send_to*]->(t))
RETURN [n IN nodes(p) WHERE n:Equipment OR any(label IN labels(n) WHERE label ENDS WITH 'Valve') OR n:SafetyValveOrFitting | n.tag] AS flow_path_tags;

MATCH (:PlantItem {tag: 'GTV-39019'})-[:send_to]->(fed:PlantItem)
RETURN DISTINCT fed.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'PGV-1005'})-[:send_to]->(fed:PlantItem)
RETURN DISTINCT fed.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:ButterflyValve)
WHERE toString(v.unit_id) = '35'
RETURN count(v) AS number, collect(v.tag) AS tags;

MATCH (item:PlantItem {tag: 'E-903'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "D-5001"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "V-3801"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;
